const t=[{id:"u1",nickname:"股市猎手",avatar:"",level:"Lv.8",posts:156,followers:892,following:128,bio:"十年老股民，专注价值投资，热爱分享交易心得",joinDate:"2024-03",color:"#f0b90b"},{id:"u2",nickname:"量化小王子",avatar:"",level:"Lv.6",posts:89,followers:456,following:234,bio:"量化交易研究者，用数据说话",joinDate:"2024-06",color:"#3b82f6"},{id:"u3",nickname:"波段捕手",avatar:"",level:"Lv.7",posts:124,followers:678,following:156,bio:"擅长波段操作，专注中短线交易机会挖掘",joinDate:"2024-01",color:"#8b5cf6"},{id:"u4",nickname:"价值发现者",avatar:"",level:"Lv.5",posts:67,followers:345,following:89,bio:"寻找被市场低估的好公司，长期持有",joinDate:"2024-08",color:"#00c897"},{id:"u5",nickname:"财经麻辣烫",avatar:"",level:"Lv.4",posts:45,followers:234,following:167,bio:"说人话的财经解读，让投资变简单",joinDate:"2025-01",color:"#06b6d4"},{id:"u6",nickname:"趋势交易者",avatar:"",level:"Lv.6",posts:98,followers:567,following:123,bio:"顺势而为，趋势是我的朋友",joinDate:"2024-05",color:"#ff4757"},{id:"u7",nickname:"AI投资助手",avatar:"",level:"Lv.9",posts:210,followers:1200,following:45,bio:"智投AI官方账号，分享AI选股策略",joinDate:"2024-01",color:"#f0b90b"},{id:"u8",nickname:"懒人养鸡",avatar:"",level:"Lv.3",posts:23,followers:89,following:56,bio:"定投爱好者，慢慢变富",joinDate:"2025-03",color:"#a78bfa"}],i=[{id:"p1",title:"宁德时代突破前高，后续怎么看？",content:"今天宁德时代放量突破192平台，创出近期新高。从盘面看资金介入明显，技术面呈现标准突破形态。大家觉得后续空间还有多大？我的目标价先看220。",author:t[0],stock:"300750.SZ",stockName:"宁德时代",category:"讨论",createdAt:"2025-05-14T10:30:00",likes:45,comments:12,views:1230,isPinned:!1,isHot:!0,tags:["热门","技术分析"]},{id:"p2",title:"半导体板块集体爆发，是反转还是反弹？",content:"今天半导体板块涨超4%，中芯国际、北方华创领涨。存储芯片价格连续三个月上涨，行业基本面确实在改善。但问题是这轮上涨能持续吗？还是只是一日游行情？",author:t[2],stock:"688981.SH",stockName:"中芯国际",category:"讨论",createdAt:"2025-05-14T09:15:00",likes:38,comments:15,views:980,isPinned:!1,isHot:!0,tags:["半导体","热议"]},{id:"p3",title:"【实盘记录】2025年5月收益+8.5%，跑赢大盘",content:"本月操作总结：1）继续持有宁德时代，浮盈12%；2）低位加仓了中国移动，吃到了这波高股息行情；3）清仓了五粮液，微亏2%止损。整体仓位6成，进可攻退可守。",author:t[0],stock:null,stockName:null,category:"实盘",createdAt:"2025-05-13T22:00:00",likes:89,comments:23,views:2450,isPinned:!1,isHot:!0,tags:["实盘","精华"]},{id:"p4",title:"聊聊我对 AI 产业链的看法",content:"今年最确定的主线就是 AI。从算力到模型到应用，每个环节都有机会。我个人最看好 AI 应用层，特别是结合中国场景的 AI 公司。科大讯飞、海康威视这些有数据优势的公司值得重点关注。",author:t[5],stock:"002230.SZ",stockName:"科大讯飞",category:"研究",createdAt:"2025-05-13T20:30:00",likes:56,comments:18,views:1560,isPinned:!1,isHot:!1,tags:["AI","深度"]},{id:"p5",title:"降准了！周一怎么看？",content:'周五盘后央行宣布降准0.5个百分点，超出市场预期。按理说是利好，但A股经常走"利好出货"的剧本。周一是高开低走还是高开高走？请大家说说看法。',author:t[4],stock:null,stockName:null,category:"讨论",createdAt:"2025-05-11T18:00:00",likes:72,comments:31,views:3200,isPinned:!0,isHot:!0,tags:["热点","政策"]},{id:"p6",title:"我的投资体系：为什么我做趋势跟踪",content:"入市十年，交过学费也赚过认知的钱。最后发现最适合我的是趋势跟踪：1）不预测顶底，只跟随趋势；2）严格止损，截断亏损让利润奔跑；3）仓位管理比选股更重要。与大家共勉。",author:t[1],stock:null,stockName:null,category:"心得",createdAt:"2025-05-11T14:00:00",likes:45,comments:9,views:890,isPinned:!1,isHot:!1,tags:["经验","系统"]},{id:"p7",title:"中国移动突破前高，高股息策略YYDS",content:"中国移动今天又新高了，从去年开始一路持有，既吃股息又吃涨幅。在当前市场环境下，高股息策略确实香。移动、电信、联通里我还是最看好移动，龙头地位稳固。",author:t[3],stock:"600941.SH",stockName:"中国移动",category:"心得",createdAt:"2025-05-11T11:30:00",likes:34,comments:8,views:670,isPinned:!1,isHot:!1,tags:["高股息"]},{id:"p8",title:"【AI选股】智投AI今日精选6只标的",content:"今日 AI 模型从全市场筛选出 6 只值得关注的标的，排名前三分别为：1）宁德时代（评分92）-主力资金持续流入；2）中国移动（评分88）-高股息防御；3）海康威视（评分85）-AI概念催化。详细分析见每日推荐模块。",author:t[6],stock:"300750.SZ",stockName:"宁德时代",category:"AI推荐",createdAt:"2025-05-14T08:30:00",likes:67,comments:14,views:1850,isPinned:!0,isHot:!0,tags:["AI精选","官方"]},{id:"p9",title:"医药板块跌到位了吗？",content:"医药跌了两年了，中证医药指数从高点回撤超过40%。CXO、创新药、器械各细分领域都跌了不少。想问问大家，医药板块现在能抄底了吗？",author:t[7],stock:"603259.SH",stockName:"药明康德",category:"讨论",createdAt:"2025-05-10T16:00:00",likes:28,comments:16,views:780,isPinned:!1,isHot:!1,tags:["医药"]},{id:"p10",title:"2025下半年投资策略：均衡配置中的进攻机会",content:"AI 模型综合宏观因子、资金流向、估值水平等多维度数据，对2025下半年做出以下判断：1）大盘整体震荡偏多；2）风格上成长优于价值；3）行业上超配科技+消费，低配周期。详细策略见每日推荐模块。",author:t[6],stock:null,stockName:null,category:"策略",createdAt:"2025-05-10T08:00:00",likes:93,comments:27,views:2800,isPinned:!0,isHot:!0,tags:["策略","官方"]}],a={p1:[{id:"c1",postId:"p1",content:"我也看好宁德时代，资金面确实不错，北向一直在买。目标价我看到230。",author:t[5],createdAt:"2025-05-14T11:00:00",likes:12,replies:[{id:"r1",content:"同意，但短期涨幅大了需要注意回调风险",author:t[0],createdAt:"2025-05-14T11:15:00",likes:5},{id:"r2",content:"230太乐观了，我觉得220先减仓比较稳妥",author:t[2],createdAt:"2025-05-14T11:30:00",likes:3}]},{id:"c2",postId:"p1",content:"技术面确实走好了，但要注意量能是否持续。今天放量是好事，但如果后续缩量就要小心了。",author:t[1],createdAt:"2025-05-14T11:20:00",likes:8,replies:[{id:"r3",content:"量能分析很到位，学习了",author:t[7],createdAt:"2025-05-14T11:45:00",likes:2}]},{id:"c3",postId:"p1",content:"拿着不动，等风来",author:t[3],createdAt:"2025-05-14T12:00:00",likes:6,replies:[]}],p3:[{id:"c4",postId:"p3",content:"大佬带带我，这收益太强了",author:t[7],createdAt:"2025-05-13T22:30:00",likes:8,replies:[{id:"r4",content:"不算大佬，分享一下仅供参考哈",author:t[0],createdAt:"2025-05-13T23:00:00",likes:4}]},{id:"c5",postId:"p3",content:"宁德时代我也是重仓，一起吃肉",author:t[2],createdAt:"2025-05-13T23:15:00",likes:5,replies:[]}],p5:[{id:"c6",postId:"p5",content:"我觉得会高开，但不要追高。等回调再加仓",author:t[0],createdAt:"2025-05-11T18:30:00",likes:15,replies:[{id:"r5",content:"同意，现在市场情绪还不是特别亢奋，高开低走可能性不大",author:t[1],createdAt:"2025-05-11T19:00:00",likes:6}]},{id:"c7",postId:"p5",content:"利好银行地产，我已经提前埋伏了招行",author:t[3],createdAt:"2025-05-11T19:30:00",likes:10,replies:[]}]},s=[{symbol:"300750.SZ",name:"宁德时代",roomName:"宁王交流圈",memberCount:2836,activePostCount:24,lastActive:"3分钟前",description:"这里是所有关注宁德时代的投资者的交流平台，欢迎分享你的分析和观点。"},{symbol:"002594.SZ",name:"比亚迪",roomName:"比粉聚集地",memberCount:2156,activePostCount:18,lastActive:"5分钟前",description:"比亚迪股票讨论圈，一起见证新能源汽车龙头的成长。"},{symbol:"688981.SH",name:"中芯国际",roomName:"芯芯相印",memberCount:1820,activePostCount:15,lastActive:"8分钟前",description:"半导体龙头交流圈，关注国产芯片自主可控进程。"},{symbol:"600941.SH",name:"中国移动",roomName:"移动之家",memberCount:1256,activePostCount:10,lastActive:"15分钟前",description:"高股息投资者聚集地，关注移动云和数字化业务。"},{symbol:"000858.SZ",name:"五粮液",roomName:"五粮液研究所",memberCount:986,activePostCount:8,lastActive:"20分钟前",description:"消费板块交流圈，关注白酒行业动态和估值变化。"},{symbol:"002415.SZ",name:"海康威视",roomName:"海康AI圈",memberCount:756,activePostCount:6,lastActive:"30分钟前",description:"AI安防龙头交流圈，关注创新业务进展和海外市场。"}];function n(e){return s.find(o=>o.symbol===e)||null}export{a as C,i as P,s as S,t as U,n as g};
